<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { ApiError } from '@/api/client';
import { createAcademicRecord, getAcademicGovernance, type AcademicGovernance } from '@/api/academic';
import { getSession } from '@/api/session';

const router = useRouter(); const data = ref<AcademicGovernance | null>(null); const section = ref<'facultad'|'campus'|'carrera'|'periodo'>('facultad'); const error = ref<string|null>(null); const message = ref<string|null>(null);
const form = ref<Record<string, unknown>>({ code: '', nombre: '' });
const reset = () => { form.value = section.value === 'carrera' ? { code: '', nombre: '', faculty_id: null, campus_id: null, modality: 'presencial', curriculum_code: '', cycle_count: 1 } : section.value === 'periodo' ? { code: '', starts_on: '', ends_on: '', teaching_weeks: 16 } : { code: '', nombre: '' }; };
const load = async () => { try { const session = await getSession(); if (session.active_role?.code !== 'administrador') { await router.replace('/panel'); return; } data.value = await getAcademicGovernance(); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo cargar la estructura académica.'; } };
const create = async () => { try { message.value = (await createAcademicRecord(section.value, form.value)).message; reset(); await load(); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo crear el registro.'; } };
const select = (value: typeof section.value) => { section.value = value; reset(); };
onMounted(() => { reset(); void load(); });
</script>

<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Administración</p><h1>Estructura académica</h1></div><RouterLink class="back-link" to="/panel">Volver al panel</RouterLink></header><p v-if="data?.lock_reason" role="alert">{{ data.lock_reason }}</p>
<nav class="header-actions"><button @click="select('facultad')">Facultades</button><button @click="select('campus')">Campus</button><button @click="select('carrera')">Carreras</button><button @click="select('periodo')">Períodos</button></nav>
<form class="detail-card" @submit.prevent="create"><h2>Crear {{ section }}</h2><template v-if="section === 'periodo'"><label>Código<input v-model="form.code" required /></label><label>Inicio<input v-model="form.starts_on" type="date" required /></label><label>Fin<input v-model="form.ends_on" type="date" required /></label><label>Semanas lectivas<input v-model="form.teaching_weeks" type="number" min="1" required /></label></template><template v-else><label>Código<input v-model="form.code" /></label><label>Nombre<input v-model="form.nombre" required /></label><template v-if="section === 'carrera'"><label>Facultad<select v-model="form.faculty_id" required><option :value="null">Seleccione</option><option v-for="faculty in data?.options.faculties" :key="faculty.id" :value="faculty.id">{{ faculty.nombre }}</option></select></label><label>Campus<select v-model="form.campus_id" required><option :value="null">Seleccione</option><option v-for="campus in data?.options.campuses" :key="campus.id" :value="campus.id">{{ campus.nombre }}</option></select></label><label>Modalidad<select v-model="form.modality"><option value="presencial">Presencial</option><option value="semipresencial">Semipresencial</option><option value="en_linea">En línea</option><option value="a_distancia">A distancia</option><option value="hibrida">Híbrida</option></select></label><label>Código malla<input v-model="form.curriculum_code" required /></label><label>Ciclos<input v-model="form.cycle_count" type="number" min="1" required /></label></template></template><button>Crear</button></form>
<p v-if="message" class="save-status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><section v-if="data" class="detail-card"><h2>Registros</h2><div class="table-wrap"><table><thead><tr><th>Nombre / código</th><th>Estado</th></tr></thead><tbody><template v-if="section === 'facultad'"><tr v-for="item in data.catalogs.faculties" :key="item.id"><td>{{ item.nombre }}<small>{{ item.codigo_facultad }}</small></td><td>{{ item.activo ? 'Activo' : 'Inactivo' }}</td></tr></template><template v-else-if="section === 'campus'"><tr v-for="item in data.catalogs.campuses" :key="item.id"><td>{{ item.nombre }}<small>{{ item.codigo_campus }}</small></td><td>{{ item.activo ? 'Activo' : 'Inactivo' }}</td></tr></template><template v-else-if="section === 'carrera'"><tr v-for="item in data.catalogs.careers" :key="item.id"><td>{{ item.name }}<small>{{ item.code }} · {{ item.modality }}</small></td><td>{{ item.active ? 'Activa' : 'Inactiva' }}</td></tr></template><template v-else><tr v-for="item in data.catalogs.periods" :key="item.id"><td>{{ item.code }}<small>{{ item.starts_on }} — {{ item.ends_on }}</small></td><td>{{ item.status_label }}</td></tr></template></tbody></table></div></section></main></template>
